地址栏会改变可视高度: dvh 跟随实际可视区, 不支持时退回 100% */\n  height: 100%;\n  height: 100dvh;\n  box-sizing: border-box;\n  /* 预留刘海屏安全区, 保证标题栏和底部按钮始终可点 */\n  padding: max(12px, env(safe-area-inset-top)) max(12px, env(safe-area-inset-right))\n    max(12px, env(safe-area-inset-bottom)) max(12px, env(safe-area-inset-left));\n  background: rgba(0, 0, 0, 0.55);\n  backdrop-filter: blur(6px);\n  display: flex;\n  justify-content: center;\n  /* 用 flex-start + 子元素 margin:auto 居中: 内容超高时不会像 align-items:center 那样把顶部裁掉 */\n  align-items: flex-start;\n  overflow-y: auto;\n  overscroll-behavior: contain;\n  z-index: 9999;\n}\n\n.preset-panel {\n  background: var(--SmartThemeBlurTintColor, #1e1e1e);\n  border: 1px solid var(--SmartThemeBorderColor, #454545);\n  border-radius: 16px;\n  box-sizing: border-box;\n  width: 100%;\n  max-width: 620px;\n  /* 上限为遮罩可视高度, 超出部分交给 .panel-body 内部滚动, 面板不会溢出屏幕 */\n  max-height: 100%;\n  margin: auto;\n  display: flex;\n  flex-direction: column;\n  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.5);\n  overflow: hidden;\n}\n\n.panel-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 14px 20px;\n  border-bottom: 1px solid var(--SmartThemeBorderColor, #454545);\n  background: linear-gradient(90deg, var(--accent-soft), transparent 60%);\n\n  h2 {\n    margin: 0;\n    font-size: 16px;\n    letter-spacing: 1px;\n    color: var(--SmartThemeBodyColor, #fff);\n  }\n\n  .close-btn {\n    background: none;\n    border: none;\n    color: var(--SmartThemeBodyColor, #fff);\n    font-size: 18px;\n    cursor: pointer;\n    opacity: 0.6;\n    transition:\n      opacity 0.2s,\n      transform 0.2s;\n\n    &:hover {\n      opacity: 1;\n      transform: rotate(90deg);\n    }\n  }\n}\n\n.panel-body {\n  flex: 1;\n  overflow-y: auto;\n  padding: 16px 20px;\n}\n\n.loading,\n.error {\n  text-align: center;\n  padding: 40px;\n  color: var(--SmartThemeBodyColor, #fff);\n}\n\n.error {\n  color: #e8836f;\n}\n\n/* ── 顶部快捷区 ───────────────────────────── */\n.quick-tabs {\n  display: flex;\n  gap: 4px;\n  padding: 4px;\n  margin-bottom: 12px;\n  border-radius: 12px;\n  background: var(--bg-card);\n  border: 1px solid var(--SmartThemeBorderColor, #454545);\n}\n\n.quick-tab {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  padding: 9px 8px;\n  border: none;\n  border-radius: 9px;\n  white-space: nowrap;\n  background: transparent;\n  color: var(--SmartThemeBodyColor, #fff);\n  font-size: 14px;\n  font-weight: 600;\n  cursor: pointer;\n  opacity: 0.65;\n  transition:\n    background 0.2s,\n    opacity 0.2s,\n    color 0.2s;\n\n  &:hover {\n    opacity: 0.9;\n  }\n\n  &.active {\n    background: var(--accent-fill);\n    color: var(--SmartThemeBodyColor, #fff);\n    opacity: 1;\n    font-weight: 700;\n    box-shadow:\n      inset 0 0 0 1px var(--accent-border),\n      0 1px 6px var(--accent-shadow);\n  }\n}\n\n.quick-panel {\n  margin-bottom: 16px;\n  padding: 14px;\n  border-radius: 12px;\n  border: 1px dashed var(--accent-border);\n  background: var(--accent-soft);\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n/* 场景按钮网格 */\n.chip-list {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 8px;\n}\n\n.chip {\n  padding: 10px 6px;\n  border: 1px solid var(--SmartThemeBorderColor, #4f4f4f);\n  border-radius: 10px;\n  background: var(--bg-card);\n  color: var(--SmartThemeBodyColor, #fff);\n  font-size: 13px;\n  cursor: pointer;\n  transition:\n    background 0.2s,\n    border-color 0.2s,\n    transform 0.15s;\n\n  &:hover {\n    background: var(--hover);\n    transform: translateY(-1px);\n  }\n\n  &.active {\n    background: var(--accent-fill-strong);\n    border-color: var(--accent-border);\n    color: var(--SmartThemeBodyColor, #fff);\n    font-weight: 600;\n    box-shadow: 0 1px 6px var(--accent-shadow);\n  }\n}\n\n.hint {\n  font-size: 12px;\n  line-height: 1.6;\n  color: var(--SmartThemeBodyColor, #fff);\n  opacity: 0.55;\n}\n\n.ungrouped-hint {\n  margin-bottom: 8px;\n}\n\n.warning {\n  font-size: 12px;\n  line-height: 1.6;\n  color: #f0b67f;\n  background: rgba(240, 182, 127, 0.12);\n  border: 1px solid rgba(240, 182, 127, 0.35);\n  border-radius: 8px;\n  padding: 8px 12px;\n  margin-bottom: 10px;\n}\n\n.config-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 8px 14px;\n}\n\n.config-row {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  min-width: 0;\n}\n\n.config-label {\n  font-size: 12px;\n  color: var(--SmartThemeBodyColor, #fff);\n  opacity: 0.65;\n}\n\n.config-select {\n  width: 100%;\n  min-width: 0;\n  padding: 6px 10px;\n  border: 1px solid var(--SmartThemeBorderColor, #4f4f4f);\n  border-radius: 8px;\n  background: var(--accent-soft);\n  color: var(--SmartThemeBodyColor, #fff);\n  font-size: 13px;\n  outline: none;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  transition: border-color 0.2s;\n\n  &:focus {\n    border-color: var(--accent);\n  }\n}\n\n.config-row--multi {\n  grid-column: 1 / -1;\n}\n\n.config-checks {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n}\n\n.config-check {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n  padding: 5px 10px;\n  border: 1px solid var(--SmartThemeBorderColor, #4f4f4f);\n  border-radius: 8px;\n  background: var(--accent-soft);\n  cursor: pointer;\n  transition:\n    background 0.2s,\n    border-color 0.2s;\n\n  &:hover {\n    background: var(--hover);\n  }\n\n  &:has(input:checked) {\n    background: var(--accent-fill);\n    border-color: var(--accent-border);\n  }\n\n  input[type='checkbox'] {\n    accent-color: var(--accent);\n    width: 14px;\n    height: 14px;\n    margin: 0;\n    cursor: pointer;\n  }\n}\n\n.config-check-label {\n  font-size: 12px;\n  color: var(--SmartThemeBodyColor, #fff);\n  white-space: nowrap;\n}\n\n.apply-config-btn {\n  align-self: flex-end;\n}\n\n/* ── 分组 ───────────────────────────── */\n.group-section {\n  margin-bottom: 10px;\n  border: 1px solid var(--SmartThemeBorderColor, #454545);\n  border-radius: 10px;\n  overflow: hidden;\n  background: var(--bg-card);\n}\n\n.group-header {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 10px 14px;\n  cursor: pointer;\n  user-select: none;\n  border-left: 3px solid var(--accent);\n  transition: background 0.2s;\n\n  &:hover {\n    background: var(--hover);\n  }\n\n  i {\n    font-size: 11px;\n    color: var(--accent);\n    opacity: 0.9;\n  }\n\n  .group-name {\n    flex: 1;\n    font-weight: 600;\n    font-size: 14px;\n    color: var(--SmartThemeBodyColor, #fff);\n  }\n\n  .group-count {\n    font-size: 11px;\n    padding: 2px 8px;\n    border-radius: 999px;\n    background: var(--accent-fill);\n    color: var(--SmartThemeBodyColor, #fff);\n    opacity: 0.7;\n  }\n}\n\n.group-items {\n  padding: 6px 10px 8px;\n}\n\n.subgroup-section {\n  margin: 4px 0;\n  border: 1px solid var(--SmartThemeBorderColor, #454545);\n  border-radius: 8px;\n  overflow: hidden;\n}\n\n.subgroup-header {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 6px 12px;\n  background: var(--bg-card);\n  cursor: pointer;\n  user-select: none;\n\n  &:hover {\n    background: var(--hover);\n  }\n\n  i {\n    font-size: 9px;\n    color: var(--SmartThemeBodyColor, #fff);\n    opacity: 0.5;\n  }\n\n  .subgroup-name {\n    flex: 1;\n    font-size: 12px;\n    font-weight: 500;\n    color: var(--SmartThemeBodyColor, #fff);\n    opacity: 0.85;\n  }\n}\n\n.subgroup-items {\n  padding: 4px 4px 4px 16px;\n}\n\n.prompt-item {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 7px 8px;\n  border-radius: 8px;\n  margin-bottom: 2px;\n\n  &:hover {\n    background: var(--hover);\n  }\n\n  &.is-marker {\n    opacity: 0.55;\n    font-style: italic;\n\n    .item-name {\n      color: var(--accent);\n    }\n  }\n\n  &.is-locked {\n    .switch {\n      cursor: not-allowed;\n      opacity: 0.4;\n\n      .slider {\n        cursor: not-allowed;\n      }\n    }\n\n    .item-name {\n      opacity: 0.7;\n    }\n  }\n}\n\n.item-name {\n  flex: 1;\n  color: var(--SmartThemeBodyColor, #fff);\n  font-size: 13px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.item-role {\n  font-size: 10px;\n  color: var(--SmartThemeBodyColor, #fff);\n  opacity: 0.35;\n  text-transform: uppercase;\n  letter-spacing: 1px;\n}\n\n/* Switch 开关 */\n.switch {\n  position: relative;\n  display: inline-block;\n  width: 38px;\n  height: 22px;\n  flex-shrink: 0;\n\n  input {\n    opacity: 0;\n    width: 0;\n    height: 0;\n\n    &:checked + .slider {\n      background-color: var(--accent);\n    }\n\n    &:checked + .slider:before {\n      transform: translateX(16px);\n      background-color: var(--accent-on);\n    }\n  }\n\n  .slider {\n    position: absolute;\n    cursor: pointer;\n    top: 0;\n    left: 0;\n    right: 0;\n    bottom: 0;\n    background-color: var(--accent-fill);\n    transition: 0.2s;\n    border-radius: 22px;\n\n    &:before {\n      position: absolute;\n      content: '';\n      height: 16px;\n      width: 16px;\n      left: 3px;\n      bottom: 3px;\n      background-color: color-mix(in srgb, var(--theme-fg) 45%, transparent);\n      transition: 0.2s;\n      border-radius: 50%;\n    }\n  }\n}\n\n.panel-footer {\n  display: flex;\n  justify-content: flex-end;\n  gap: 10px;\n  padding: 14px 20px;\n  border-top: 1px solid var(--SmartThemeBorderColor, #454545);\n}\n\n.btn {\n  padding: 8px 18px;\n  border: none;\n  border-radius: 8px;\n  cursor: pointer;\n  font-size: 13px;\n  font-weight: 600;\n  transition:\n    background 0.2s,\n    transform 0.15s;\n\n  &:hover {\n    transform: translateY(-1px);\n  }\n\n  &.btn-primary {\n    background: var(--accent-fill-strong);\n    color: var(--SmartThemeBodyColor, #fff);\n    border: 1px solid var(--accent-border);\n    box-shadow: 0 2px 10px var(--accent-shadow);\n\n    &:hover {\n      background: color-mix(in srgb, var(--theme-fg) 36%, transparent);\n    }\n  }\n\n  &.btn-secondary {\n    background: transparent;\n    color: var(--SmartThemeBodyColor, #fff);\n    border: 1px solid var(--SmartThemeBorderColor, #4f4f4f);\n\n    &:hover {\n      background: var(--hover);\n    }\n  }\n}\n\n/* ── 移动端适配 ───────────────────────────── */\n@media (max-width: 768px) {\n  .preset-panel {\n    border-radius: 12px;\n  }\n\n  .panel-header {\n    padding: 12px 14px;\n\n    h2 {\n      font-size: 15px;\n    }\n  }\n\n  .panel-body {\n    padding: 12px 12px;\n  }\n\n  .quick-tab {\n    padding: 10px 4px;\n    font-size: 12px;\n    gap: 4px;\n  }\n\n  .quick-panel {\n    padding: 12px 10px;\n  }\n\n  /* 窄屏下三列会把场景名挤成竖排, 改两列 */\n  .chip-list {\n    grid-template-columns: repeat(2, 1fr);\n  }\n\n  /* 下拉框单列排布, 避免选项文字被截断 */\n  .config-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .apply-config-btn {\n    align-self: stretch;\n  }\n\n  .group-header {\n    padding: 10px 10px;\n  }\n\n  .group-items {\n    padding: 6px 6px 8px;\n  }\n\n  .subgroup-items {\n    padding: 4px 2px 4px 10px;\n  }\n\n  .prompt-item {\n    gap: 8px;\n    padding: 8px 6px;\n  }\n\n  /* 触摸目标保持够大, 同时给条目名留出宽度 */\n  .switch {\n    width: 42px;\n    height: 24px;\n\n    input:checked + .slider:before {\n      transform: translateX(18px);\n    }\n\n    .slider:before {\n      height: 18px;\n      width: 18px;\n    }\n  }\n\n  .item-role {\n    display: none;\n  }\n\n  .panel-footer {\n    padding: 12px 12px;\n    gap: 8px;\n  }\n\n  /* 底部按钮平分宽度, 单手也能点到 */\n  .btn {\n    flex: 1;\n    padding: 11px 10px;\n  }\n}\n"],"sourceRoot":""}]);
